DO $$
DECLARE
  r RECORD;
  cur_status INT;
  cur_minutes INT;
BEGIN
  FOR r IN SELECT * FROM watch_events ORDER BY event_id LOOP
    SELECT watch_status, total_watch_minutes INTO cur_status, cur_minutes
    FROM content_state
    WHERE content_id = r.content_id AND viewer_id = r.viewer_id;

    IF r.event_type = 1 AND cur_status = 0 THEN
      UPDATE content_state
      SET watch_status = 1, total_watch_minutes = cur_minutes + r.minutes_watched
      WHERE content_id = r.content_id AND viewer_id = r.viewer_id;
    ELSIF r.event_type = 2 AND cur_status = 1 THEN
      UPDATE content_state
      SET total_watch_minutes = cur_minutes + r.minutes_watched
      WHERE content_id = r.content_id AND viewer_id = r.viewer_id;
    ELSIF r.event_type = 3 AND (cur_status = 1 OR cur_status = 2) THEN
      UPDATE content_state
      SET watch_status = 2, total_watch_minutes = cur_minutes + r.minutes_watched
      WHERE content_id = r.content_id AND viewer_id = r.viewer_id;
    END IF;
  END LOOP;
END $$;

SELECT * FROM content_state ORDER BY content_id, viewer_id;

